    for (int i = 0; i < 2; i++) {
        printf("h[%d] = %f\n", i, h[i]);
    }

    printf("\nDetail coefficients (g):\n");
    for (int i = 0; i < 2; i++) {
        printf("g[%d] = %f\n", i, g[i]);
    }

    return 0;
}
